import { type ChangeEvent, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, peopleKey, personActionKey, useLatestPersonAction } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { poolsKey } from '../pools/pools';
import { useColumnShown } from '../columns/columns';

function HoldHead() {
  if (!useColumnShown()('hold')) return null;
  return <th>Hold</th>;
}

// Whether the person has any hold, a line for each of their holds, and the dates and button that add
// one (a blank from-date takes the sheet's today, a blank to-date has no end). A hold leaves their
// claims in every total; one in force on today only takes their cuts. A refused hold shows its error
// until the dates are changed or the next is tried.
function PersonHold({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [fields, setFields] = useState({ from: '', to: '' });
  const queryClient = useQueryClient();

  const hold = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: (dates: { from: string; to: string }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/hold`, { ...dates, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      // a hold in force on today takes the person's cuts from their pools
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
      setFields({ from: '', to: '' });
    },
  });

  const set = (k: 'from' | 'to') => (e: ChangeEvent<HTMLInputElement>) => {
    hold.reset();
    setFields((f) => ({ ...f, [k]: e.target.value }));
  };

  const latest = useLatestPersonAction(sheet, person.id);
  const shown = useColumnShown();

  if (!shown('hold')) return null;
  return (
    <td>
      <span data-testid="person-hold">{person.held ? 'yes' : 'no'}</span>
      {person.holds.map((h, i) => (
        <div key={i} data-testid="person-hold-line">
          {h.from} – {h.to ?? 'open'}
        </div>
      ))}
      <input type="date" data-testid="person-hold-from" aria-label="Hold from" value={fields.from} onChange={set('from')} />
      <input type="date" data-testid="person-hold-to" aria-label="Hold to" value={fields.to} onChange={set('to')} />
      <button
        type="button"
        data-testid="person-hold-toggle"
        disabled={hold.isPending}
        onClick={() => {
          hold.reset();
          hold.mutate(fields);
        }}
      >
        Hold
      </button>
      {hold.isError && hold.submittedAt >= latest && (
        <span data-testid="person-error" role="alert">
          {' '}
          {hold.error instanceof HttpError && hold.error.reason ? `${hold.error.reason}.` : 'The hold was refused.'}
        </span>
      )}
    </td>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 19.5, Component: HoldHead }),
  PersonColumns.fill({ order: 19.5, Component: PersonHold }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { sheetKey } from '../sheet/sheet';
import { useSelectedPeople } from './people';
import { useGradeCodes } from '../grades/grades';

type BulkGradeResult = { graded: number };

// Gives the selected people a grade together, from the from-date (the sheet's today when blank): the
// server edits each in list order as the person form would, and the count shows once it answers (gone
// while it runs). A refusal changes nothing.
function BulkGrade() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const grades = useGradeCodes(sheet);
  const [selected, setSelected] = useSelectedPeople();
  const [grade, setGrade] = useState<string>('A');
  const [from, setFrom] = useState('');
  const queryClient = useQueryClient();

  const bulk = useMutation({
    mutationFn: (p: { personIds: number[]; grade: string; gradeFrom: string }) =>
      postJson<BulkGradeResult>(`/api/sheets/${encodeURIComponent(sheet)}/bulk-grade`, {
        personIds: p.personIds.map(String),
        grade: p.grade,
        gradeFrom: p.gradeFrom,
        user,
      }),
    onSuccess: async () => {
      setSelected([]);
      // Grades move people's figures and their claims' dues, so the whole sheet is re-read.
      await queryClient.invalidateQueries({ queryKey: sheetKey(sheet) });
    },
  });
  const submit = useSubmitOnce(bulk);

  return (
    <p>
      <select
        data-testid="bulk-grade"
        aria-label="Grade for the selected people"
        value={grade}
        onChange={(e) => {
          setGrade(e.target.value);
          bulk.reset();
        }}
      >
        {grades.map((g) => (
          <option key={g} value={g}>
            {g}
          </option>
        ))}
      </select>{' '}
      <input
        data-testid="bulk-grade-from"
        type="date"
        aria-label="Grade from (blank for the sheet's today)"
        value={from}
        onChange={(e) => {
          setFrom(e.target.value);
          bulk.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="bulk-grade-apply"
        disabled={bulk.isPending}
        onClick={() => submit({ personIds: selected, grade, gradeFrom: from })}
      >
        Grade selected
      </button>
      {bulk.isSuccess && (
        <>
          {' '}
          Changed <strong data-testid="bulk-graded">{bulk.data.graded}</strong>
        </>
      )}
      {bulk.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          {bulk.error instanceof HttpError && bulk.error.reason ? `${bulk.error.reason}.` : 'The bulk grade was refused.'}
        </span>
      )}
    </p>
  );
}

export const contribution = HomeMain.fill({ order: 21, Component: BulkGrade });
